mapper.select:
SELECT d.id, d.title, d.is_private, d.status, d.view_count, d.comment_count, d.like_count,
       d.created_at, d.updated_at,
       d.mood_id, m.emoji AS moodEmoji, d.weather_id, w.emoji AS weatherEmoji
FROM diary as d
         LEFT JOIN mood as m ON m.id = d.mood_id
         LEFT JOIN weather as w ON w.id = d.weather_id
WHERE d.deleted = 0

    AND d.title like "%${title}%"


    AND d.mood_id = #{moodId}


    AND d.weather_id = #{weatherId}


    AND d.is_private = #{isPrivate}


    AND d.status = #{status}

ORDER BY d.created_at DESC
